args.sql:
SELECT AVG(
    (length(c.genreclass->>'Hierarchical_Genres') - length(replace(c.genreclass->>'Hierarchical_Genres', '~', ''))) +
    (length(c.genreclass->>'Hierarchical_Genres') - length(replace(c.genreclass->>'Hierarchical_Genres', '|', ''))) + 1
)::numeric FROM core c
JOIN content_info ci ON c.content_key = ci.content_key
WHERE (ci.mediacounts->'content_volumes'->>'Clips_Total')::int + (ci.mediacounts->'content_volumes'->>'Film_Clips')::int > (ci.mediacounts->'content_volumes'->>'Feature_Films')::int;

